"use strict";
/**
 * COMP question bank entry point.
 *
 * Browser: include tools/categories/index.js and every category file, then read
 *          window.QBANK (the loader in assets/js/qbank-loader.js does this).
 * Node:    const qbank = require("./qbank.js");
 *
 * Everything here is generated by tools/build-qbank.js — rebuild with:
 *   node tools/build-qbank.js
 */
(function (root, factory) {
  if (typeof module === "object" && module.exports) {
    module.exports = factory(require("./tools/categories/index.js"), null, true);
  } else {
    root.QBANK = factory(root.QBANK_MANIFEST || [], root.QBANK_CATEGORIES || {}, false);
  }
})(typeof self !== "undefined" ? self : this, function (manifest, store, isNode) {
  function catalogue() {
    if (isNode) {
      return manifest.map(function (entry) {
        return require("./tools/categories/" + entry.file + ".js");
      });
    }
    var out = [];
    manifest.forEach(function (entry) {
      if (entry.parts && entry.partDir) {
        for (var p = 1; p <= entry.parts; p++) {
          var key = entry.slug + ":part-" + (p < 10 ? "0" + p : p);
          if (store[key]) out.push(store[key]);
        }
      } else if (store[entry.slug]) {
        out.push(store[entry.slug]);
      }
    });
    return out;
  }

  function all() {
    var out = [];
    catalogue().forEach(function (c) { out = out.concat(c.questions || []); });
    return out;
  }

  function bySlug(slug) {
    var found = [];
    catalogue().forEach(function (c) {
      if (c.slug === slug || (c.parent && c.parent === slug)) found = found.concat(c.questions || []);
    });
    return found;
  }

  /** Competition rules used by every paper on the site. */
  var examRules = { questions: 40, minutes: 40, correctMark: 1, negativeMark: 0.25 };

  var exams = [
    { id: "ssc-cgl", name: "SSC CGL", sections: ["reasoning", "general-awareness", "quantitative-aptitude", "english"] },
    { id: "ssc-chsl", name: "SSC CHSL", sections: ["reasoning", "general-awareness", "quantitative-aptitude", "english"] },
    { id: "banking", name: "Banking (IBPS / SBI)", sections: ["reasoning", "quantitative-aptitude", "english", "general-awareness", "computer-awareness"] },
    { id: "railways", name: "Railways (RRB NTPC / Group D)", sections: ["mathematics", "reasoning", "general-awareness"] }
  ];

  var classes = ["Class 1", "Class 2", "Class 3", "Class 4", "Class 5", "Class 6", "Class 7", "Class 8",
    "Class 9", "Class 10", "Class 11", "Class 12", "Graduation"];

  var bank = {
    generatedBy: "tools/build-qbank.js",
    manifest: manifest,
    categories: catalogue,
    questions: all,
    bySlug: bySlug,
    exams: exams,
    classes: classes,
    examRules: examRules,
    totals: function () {
      var t = {};
      catalogue().forEach(function (c) { t[c.slug] = (c.questions || []).length; });
      return t;
    }
  };

  if (typeof window !== "undefined") window.QBANK = bank;
  return bank;
});
